#!/bin/sh
# =============================================================================
# stock_trader \uc774\ubbf8\uc9c0 entrypoint.
# -----------------------------------------------------------------------------
# \uc5ed\ud560:
#   1. \ub9c8\uc6b4\ud2b8\ub41c \ud638\uc2a4\ud2b8 \uc1bc\ub9bd \ub514\ub809\ud130\ub9ac(`/app/data/*`, `/app/docs_cache`)\uc758
#      \uc18c\uc720\uc790\ub97c \ucee8\ud14c\uc774\ub108 \ub0b4 `app` \uc720\uc800(uid 1000)\ub85c \uc870\uc815.
#      bind mount\ub294 \ud638\uc2a4\ud2b8 \uad8c\ud55c\uc744 \uadf8\ub300\ub85c \uac00\uc838\uc624\uae30 \ub54c\ubb38\uc5d0, Dockerfile\uc758\n#      `chown`\uc740 \ub9c8\uc6b4\ud2b8 \uc9c0\uc810\uc5d0\uc11c \ubb34\ud6a8\ud654\ub41c\ub2e4. \ub9e4 \uae30\ub3d9 \uc2dc \ucabc\uc7a5\uc73c\ub85c \uc870\uc815.\n#   2. \uc870\uc815 \ud6c4 `app` \uc720\uc800\ub85c privilege drop \ud558\uace0 \uc6d0\ub798 CMD \uc2e4\ud589.\n#\n# \uc774 \uc2a4\ud06c\ub9bd\uc740 root\ub85c \uc2dc\uc791\ud574\uc11c chown\ub9cc \uc218\ud589\ud55c \ub4a4 \uc989\uc2dc \ud2b9\uad8c\uc744 \ubc84\ub9ac\ubbc0\ub85c,\n# \uc870\uc7a5\ub41c \ucee8\ud14c\uc774\ub108 \ub0b4\ubd80 \ud504\ub85c\uc138\uc2a4\ub294 \uc885\uad6c \uc774\uc804\uacfc \ub3d9\uc77c\ud558\uac8c \ube44-root\ub85c \ub3d9\uc791\ud55c\ub2e4.\n#\n# tini \ub54c\ubb38\uc5d0 PID 1\uc740 tini\uac00 \uc7a1\uace0, \uc774 \uc2a4\ud06c\ub9bd\uc740 PID 2\ub85c \uc2e4\ud589\ub418\uba70\n# \ucd5c\uc885 exec\uc73c\ub85c \uad50\uccb4\ub418\ub294 python \ud504\ub85c\uc138\uc2a4\ub3c4 PID 2\ub97c \uc774\uc5b4\ubc1b\ub294\ub2e4 \u2014 \ub0b4\ubd80\n# \uc2dc\uadf8\ub110 \ud578\ub4e4\ub9c1\uc740 tini\uac00 \uc6d0\ub798 \ub2f4\ub2f9.\n\nset -e

APP_USER="${APP_USER:-app}"
APP_UID="${APP_UID:-1000}"
APP_GID="${APP_GID:-1000}"

# \uad8c\ud55c\uc744 \ub9de\ucda4 \ub300\uc0c1 \ub514\ub809\ud130\ub9ac. \ucee8\ud14c\uc774\ub108\uc5d0 \ub9c8\uc6b4\ud2b8\ub420 \uc218 \uc788\ub294 \ubaa8\ub4e0
# bind mount \uc9c0\uc810\uc744 \uc5ec\uae30 \ucc28\uace0 \ub179\ucef4\ud55c\ub2e4. mkdir -p \ub294 \uc774\ubbf8 \uc874\uc7ac\ud574\ub3c4 OK,
# \ub9c8\uc6b4\ud2b8\ub418\uc9c0 \uc54a\uc740 \uacbd\uc6b0\ub3c4 \ub514\ub809\ud130\ub9ac\uac00 \uc0dd\uc131\ub418\uc5b4 \ub3d9\uc77c\ud55c \ub808\uc774\uc544\uc6c3\uc744 \uc720\uc9c0.
TARGETS="/app/data/logs /app/data/kis /app/data /app/docs_cache"

# root\uc77c \ub54c\ub9cc chown. \uc5b4\ub5a4 \uc774\uc720\ub85c \ube44-root\ub85c \uc774 \uc2a4\ud06c\ub9bd\uc774 \ubd88\ub9bf\uc744 \uacbd\uc6b0
# (\uc608: docker run --user 1000), \uc870\uc815 \uc790\uccb4\ub97c \uac74\ub108\ub6f0\uace0 \uadf8\ub300\ub85c \uc2e4\ud589\ud55c\ub2e4.
if [ "$(id -u)" = "0" ]; then
    for d in $TARGETS; do
        mkdir -p "$d"
        # \uc774\ubbf8 \uc6c3\ub0b4 \uc18c\uc720\uc790\uac00 \ub9de\uc73c\uba74 chown\uc774 \uace7\uc7a5 \uc2a4\ud0a4\ud544. -h \uc548 \uc4f0\ub294\n        # \uc774\uc720\ub294 \ub9c8\uc6b4\ud2b8 \uc9c0\uc810\uc5d0 \uc2ec\ubcfc\ub9c1\ud06c\uac00 \uc788\uc744 \uc774\uc720\uac00 \uc5c6\uc5b4\uc11c.
        chown -R "${APP_UID}:${APP_GID}" "$d"
    done

    # gosu\uac00 \uc124\uce58\ub418\uc5b4 \uc788\uc73c\uba74 \uadf8\uac8c \uace0\uc218\uc774\uc9c0\ub9cc, slim \uc774\ubbf8\uc9c0\uc5d0 \uae30\ubcf8\n    # \ud3ec\ud568\ub418\uc9c0 \uc54a\uc73c\ubbc0\ub85c \ucd94\uac00 \ud328\ud0a4\uc9c0 \uc124\uce58\ub97c \ud53c\ud558\uae30 \uc704\ud574 `su` \ub98c\ucef4\ub9e8\ub4dc\ub85c\n    # privilege drop. -s \ub85c \uc170 \uba85\uc2dc, -c \ub85c \ub2e8\ub09c \uba85\ub839 \uc2e4\ud589.\n    #\n    # exec\uc740 PID\ub97c \uc720\uc9c0\ud574 tini\uc758 \uc790\uc2dd\uc73c\ub85c \uc788\uac8c \ud574\uc8fc\uace0, sh -c $@ \ud328\ud134\uc73c\ub85c\n    # CMD\uc758 \uc778\uc790\ub4e4\uc744 \uc628\uc804\ud558\uac8c \uc804\ub2ec.\n    exec su -s /bin/sh -c 'exec "$0" "$@"' "$APP_USER" -- "$@"
fi

# \uc774\ubbf8 \ube44-root\ub85c \ub4e4\uc5b4\uc628 \uacbd\uc6b0 \u2014 \uadf8\ub0e5 \uc6d0\ub798 \uba85\ub839 \uc2e4\ud589.
exec "$@"
